<p>\u041E\u043A\u0440\u0435\u043C\u043E \u0441\u0443\u0434 \u0432\u0440\u0430\u0445\u0443\u0432\u0430\u0432, \u0449\u043E \u043F\u043E\u0441\u0430\u0434\u0438, \u044F\u043A\u0456 \u0437\u0430\u0439\u043C\u0430\u043B\u0430 \u043F\u043E\u0437\u0438\u0432\u0430\u0447\u043A\u0430, \u043D\u0430\u043B\u0435\u0436\u0430\u0442\u044C \u0434\u043E \u043F\u043E\u0441\u0430\u0434 \u0437\u0456 \u0421\u043F\u0438\u0441\u043A\u0443 \u21161 \u0437\u0433\u0456\u0434\u043D\u043E \u0437 \u041F\u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043E\u044E \u041A\u0430\u0431\u0456\u043D\u0435\u0442\u0443 \u041C\u0456\u043D\u0456\u0441\u0442\u0440\u0456\u0432 \u0423\u043A\u0440\u0430\u0457\u043D\u0438 \u0432\u0456\u0434 24 \u0447\u0435\u0440\u0432\u043D\u044F 2016 \u0440\u043E\u043A\u0443 \u2116461 \u2014 \u0456 \u0446\u0435\u0439 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440 \u0440\u043E\u0431\u043E\u0442\u0438 \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0432\u0430\u0432\u0441\u044F \u0441\u0430\u043C\u0438\u043C\u0438 \u0437\u0430\u043F\u0438\u0441\u0430\u043C\u0438 \u0442\u0440\u0443\u0434\u043E\u0432\u043E\u0457 \u043A\u043D\u0438\u0436\u043A\u0438, \u0431\u0435\u0437 \u043F\u043E\u0442\u0440\u0435\u0431\u0438 \u0432 \u0434\u043E\u0434\u0430\u0442\u043A\u043E\u0432\u0438\u0445 \u0434\u043E\u0432\u0456\u0434\u043A\u0430\u0445 \u043F\u0456\u0434\u043F\u0440\u0438\u0454\u043C\u0441\u0442\u0432\u0430.</p>
